/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-cta-bento .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; transition: transform 0.3s ease, box-shadow 0.3s ease; }
.sl-cta-bento .sl-btn-primary:hover { transform: translateY(-3px); box-shadow: 0 10px 20px rgba(0,0,0,0.2) !important; filter: brightness(0.9); }

.sl-cta-bento .sl-bento-main-btn { transition: transform 0.2s ease, box-shadow 0.2s ease; color: var(--smartlearn-primary) !important; }
.sl-cta-bento .sl-bento-main-btn:hover { transform: translateY(-2px); box-shadow: 0 5px 15px rgba(0,0,0,0.1); }
.sl-cta-bento .sl-hover-lift { transition: transform 0.2s ease, box-shadow 0.2s ease; }
.sl-cta-bento .sl-hover-lift:hover { transform: translateY(-4px); box-shadow: 0 10px 25px rgba(0,0,0,0.05) !important; border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; }
@media (prefers-reduced-motion: reduce) {
    .sl-cta-bento .sl-bento-main-btn, .sl-cta-bento .sl-hover-lift { transition: none; }
    .sl-cta-bento .sl-bento-main-btn:hover, .sl-cta-bento .sl-hover-lift:hover { transform: none; }
}
